import { ChevronRightIcon, MoreHorizontalIcon } from "lucide-react"
import * as React from "react"
import { mergeProps } from "@base-ui/react/merge-props"
import { useRender } from "@base-ui/react/use-render"

import { cn } from "@/lib/utils"
import { withReact18Ref } from "@/lib/applique-react18-compat"
function BreadcrumbImpl({ className, ...props }: React.ComponentProps<"nav">) {
  return (
    <nav
      aria-label="breadcrumb"
      data-applique-component="" data-slot="breadcrumb"
      className={cn(className)}
      {...props}
    />
  )
}

function BreadcrumbListImpl({ className, ...props }: React.ComponentProps<"ol">) {
  return (
    <ol
      data-applique-component="" data-slot="breadcrumb-list"
      className={cn(
        "flex flex-wrap items-center gap-1.5 text-sm wrap-break-word text-muted-foreground",
        className
      )}
      {...props}
    />
  )
}

function BreadcrumbItemImpl({ className, ...props }: React.ComponentProps<"li">) {
  return (
    <li
      data-applique-component="" data-slot="breadcrumb-item"
      className={cn("inline-flex items-center gap-1", className)}
      {...props}
    />
  )
}

function BreadcrumbLinkImpl({
  className,
  render,
  ...props
}: useRender.ComponentProps<"a">) {
  return useRender({
    defaultTagName: "a",
    props: mergeProps<"a">(
      {
        className: cn("transition-colors hover:text-foreground", className),
      },
      props
    ),
    render,
    state: {
      'applique-component': true,
      slot: "breadcrumb-link",
    },
  })
}

function BreadcrumbPageImpl({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-applique-component="" data-slot="breadcrumb-page"
      role="link"
      aria-disabled="true"
      aria-current="page"
      className={cn("font-normal text-foreground", className)}
      {...props}
    />
  )
}

function BreadcrumbSeparatorImpl({
  children,
  className,
  ...props
}: React.ComponentProps<"li">) {
  return (
    <li
      data-applique-component="" data-slot="breadcrumb-separator"
      role="presentation"
      aria-hidden="true"
      className={cn("[&>svg]:size-3.5", className)}
      {...props}
    >
      {children ?? (
        <ChevronRightIcon
          className="cn-rtl-flip"
         />
      )}
    </li>
  )
}

function BreadcrumbEllipsisImpl({
  className,
  ...props
}: React.ComponentProps<"span">) {
  return (
    <span
      data-applique-component="" data-slot="breadcrumb-ellipsis"
      role="presentation"
      aria-hidden="true"
      className={cn(
        "flex size-5 items-center justify-center [&>svg]:size-4",
        className
      )}
      {...props}
    >
      <MoreHorizontalIcon
       />
      <span className="sr-only">More</span>
    </span>
  )
}

const Breadcrumb = withReact18Ref(BreadcrumbImpl)
const BreadcrumbList = withReact18Ref(BreadcrumbListImpl)
const BreadcrumbItem = withReact18Ref(BreadcrumbItemImpl)
const BreadcrumbLink = withReact18Ref(BreadcrumbLinkImpl)
const BreadcrumbPage = withReact18Ref(BreadcrumbPageImpl)
const BreadcrumbSeparator = withReact18Ref(BreadcrumbSeparatorImpl)
const BreadcrumbEllipsis = withReact18Ref(BreadcrumbEllipsisImpl)

export {
  Breadcrumb,
  BreadcrumbList,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbPage,
  BreadcrumbSeparator,
  BreadcrumbEllipsis,
}
